args.sql:
SELECT COUNT(*) FROM riskandmargin 
WHERE risk_margin_profile->'position'->>'possum' IS NOT NULL 
AND risk_margin_profile->'position'->>'posmagn' IS NOT NULL;

SELECT COUNT(*) FROM riskandmargin r
JOIN orders o ON r.ordervault = o.recordvault
WHERE o.userlink IS NULL;

SELECT COUNT(*) FROM riskandmargin r
JOIN orders o ON r.ordervault = o.recordvault
JOIN users u ON o.userlink = u.userstamp;

SELECT COUNT(*) FROM riskandmargin r
JOIN orders o ON r.ordervault = o.recordvault
WHERE o.userlink IS NOT NULL AND o.userlink != '';

SELECT COUNT(*) FROM riskandmargin r 
JOIN orders o ON r.ordervault = o.recordvault
JOIN accountbalances ab ON ab.accountbalancesnode = r.riskandmarginpivot;

SELECT COUNT(*) FROM riskandmargin r 
JOIN orders o ON r.ordervault = o.recordvault
JOIN accountbalances ab ON ab.accountbalancesnode = (r.riskandmarginpivot % 999) + 1;

SELECT COUNT(*) FROM riskandmargin r 
JOIN accountbalances ab ON ab.accountbalancesnode = r.riskandmarginpivot
WHERE risk_margin_profile->'position'->>'posedge' IS NOT NULL;
